def get_words():
    """Return dict of word sets by length."""
    result = {}
    for length, text in [(3, W3), (4, W4), (5, W5), (6, W6), (7, W7)]:
        words = set()
        for w in text.split():
            w = w.strip().upper()
            if w.isalpha() and len(w) == length:
                words.add(w)
        result[length] = words
    return result

if __name__ == "__main__":
    words = get_words()
    for n in sorted(words.keys()):
        print(f"  {n}-letter: {len(words[n])}")
